import {chromium} from '@playwright/test';
import {readFile,writeFile} from 'node:fs/promises';
import {execFileSync} from 'node:child_process';
import {join} from 'node:path';
const launch=chromium.launch.bind(chromium);let patched=false;
chromium.launch=async options=>{
 const browser=await launch({...options,executablePath:'/usr/bin/chromium',args:[...(options?.args??[]),'--no-sandbox']});
 const newContext=browser.newContext.bind(browser);
 browser.newContext=async options=>{
  const context=await newContext(options);
  context.on('page',page=>{
   if(patched)return;patched=true;
   const proto=Object.getPrototypeOf(page.locator('body')),screenshot=proto.screenshot;
   proto.screenshot=async function(options){
    if(options?.path?.includes('local-members-')){
     const page=this.page();await page.evaluate(()=>scrollTo(0,0));const box=await this.boundingBox();
     return page.screenshot({...options,fullPage:true,clip:{x:0,y:box.y,width:page.viewportSize().width,height:box.height}});
    }
    return screenshot.call(this,options);
   };
  });return context;
 };return browser;
};
const head=execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim();
const {localMailFlow}=await import('../tests/team-browser.mjs');await localMailFlow();
const packet=process.env.SPOOL_LOCAL_MAIL_EVIDENCE;
const files=[];for(const width of [1440,390]){const name=`local-members-${width}.png`,data=await readFile(join(packet,name));files.push({path:name,viewport:width,pngWidth:data.readUInt32BE(16),pngHeight:data.readUInt32BE(20),invitationTokenMasked:true});if(files.at(-1).pngWidth!==width)throw Error('Proof image width mismatch');}
await writeFile(join(packet,'browser-proof-receipt.json'),JSON.stringify({head,productCheckoutClean:execFileSync('git',['status','--porcelain'],{encoding:'utf8'}).trim()==='',command:'cloud_run node .artifacts/proof-run.mjs',files},null,2)+'\n');
console.log('Exact-candidate local proof passed at 1440 and 390; invitation tokens masked.');
